=Você é um assistente encarregado de classificar e-mails. Analise o e-mail abaixo e responda APENAS com um JSON válido, sem texto extra:

{
  "categoria": "...",
  "urgencia": "alta|media|baixa",
  "resumo": "..."
}

Categorias permitidas: Urgente, Faculdade, Vagas, Financeiro, Newsletter, Promoções, Outros.

E-mail para análise:
Assunto: {{ $json.subject }}
Remetente: {{ $json.from.text }}
Conteúdo: {{ $json.textAsSimple }}

parameters.jsCode:
let rawText = "";

if ($input.item.json.content && $input.item.json.content.parts) {
  rawText = $input.item.json.content.parts[0].text;
} else if ($input.item.json.text) {
  rawText = $input.item.json.text;
} else {
  rawText = JSON.stringify($input.item.json);
}

rawText = rawText.replace(/```json/g, "").replace(/```/g, "").trim();

let categoria = "Outros";

try {
  const parsed = JSON.parse(rawText);
  if (parsed.categoria) {
    categoria = parsed.categoria;
  }
} catch (e) {
  categoria = "Outros";
}

return {
  categoria: categoria
};

// 1. Procura a categoria gerada pela IA (pega do nó de código anterior, qualquer que seja o nome)
let categoriaIA = "Outros";

try {
  // Procura o nó Code anterior que fez o parse da categoria
  const nodeCodeAnterior = $('Code in JavaScript') || $('Code');
  if (nodeCodeAnterior && nodeCodeAnterior.item && nodeCodeAnterior.item.json.categoria) {
    categoriaIA = nodeCodeAnterior.item.json.categoria;
  }
} catch (e) {
  categoriaIA = "Outros";
}

// 2. Lê a lista completa de 22 marcadores retornada pelo nó 'Get many labels'
const labelsDoGmail = $('Get many labels').all();

// 3. Encontra a etiqueta correspondente pelo nome
let labelEncontrada = labelsDoGmail.find(item => 
  item.json.name && item.json.name.toLowerCase() === categoriaIA.toLowerCase()
);

// Fallback: se não encontrar exato, usa a etiqueta "Outros"
if (!labelEncontrada) {
  labelEncontrada = labelsDoGmail.find(item => 
    item.json.name && item.json.name.toLowerCase() === "outros"
  );
}

return {
  categoriaNome: categoriaIA,
  labelId: labelEncontrada ? labelEncontrada.json.id : null
};
